def transform_gp_structure(individual, X):
    expr = gp.compile(expr=individual, pset=pset)
    X_arr = np.asarray(X)
    # Apply GP expression to each sample using only the first two inputs expected by pset
    return np.array([expr(row[0], row[1]) for row in X_arr]).reshape(-1, 1)


